const float TAU    = 6.28318530717958647693,
            PI     = 3.14159265358979323846,
            INVPI  =  .31830988618379067154,
            INV4PI =  .07957747154594766788;

vec3 c1 = vec3(1.9, .5, .5),
     c2 = vec3(0, .225, .45), // ocean color
     c3 = vec3(1, .6, .6); // bell color

#define sqr(x) (x) * (x)

/*
a smooth step(not to be confused with smoothstep)
if v > 0: x < 0: approaches 1
          x > 0: approaches 0

if v < 0: x < 0: approaches 0
          x > 0: approaches 1
*/

float eStep(float x)
{
    return exp(-exp(x));
}

float eStep(float x, float v)
{
    return eStep(v * x);
}

// a very bad smooth noise, gets more detailed when s gets larger
float T(vec2 p, float s)
{
    float k = pow(1.15, s) * 10.; // magic constant

    float a = 1. + cos(10. * s),
          b = cos(7. * s) * p.x + sin(7. * s) * p.y,
          c = 2. * cos(17. * s),
          d = 2. * cos(5. * s),
          e = cos(7. * s) * p.y - sin(7. * s) * p.x,
          f = 2. * cos(15. * s),
          g = cos(8. * s) * p.x + sin(8. * s) * p.y,
          h = 2. * cos(7. * s);

    return   cos(k * a * (b + c) + 4. * cos(k * b) + d)
           * cos(k * a * (e + f) + 4. * cos(k * g) + h);
}

// a very bad fbm
float E(vec2 p)
{
    float tot = 0.,
          amp = .3;

    for(float s = 1.; s <= 50.; s++)
    {
        amp *= 25. / 26.; // smaller details contribute less
        tot += amp * T(p, s);
    }

    return tot;
}

// clamp the color to 0 to 1 
float F(float x)
{
    return eStep(x, -1000.) * pow(x, eStep(x - 1., 1000.));
}

// tentacles shaping function
float L(vec2 p, int v)
{   
    // make the tentacles bulges out at the middle(a is smallest at the middle)
    float a = .7 + 1.5 * eStep(p.y - .27, 400.) * sqr(p.y + .2),

    // "bend" the tentacles to be more natural
          b = eStep(p.y - .3, 400.) * (.3 * sqr(p.y - .3) + .05 * cos(5. * p.y + 6. * p.x + float(v)));

    return a * p.x + b;
}

// The tentacles
float R(vec2 p, int v)
{
    float L    = L(p, v),
          absL = abs(L),

          // explan later :)
          a = .5 + INVPI * atan(-180. * absL + 100.),

          // multiply L by a to deal with out of range acos
          // (NaN is hard to deal with :( )
          // and then plug it into acos to make the tentacles kinda wraps around the cylinder
          // (trignometrics are circle related amirite? :) )
          b = float(v) + 30. * acos(1.8 * L * a),

          // if c is closer to 1, the tentacles are smaller
          // if c is close to 0, the tentacles are BIGGG
          // first, shape the tentacles to be smaller at the tip (the atan mess)
          // and the making the top bigger by make c smaller at the top
          // by minus that by the pow thingy
          c = .1 * pow(abs(p.y), 6.) - .02 - 2. * INVPI * atan(200. * (p.y - .25)),
          d = eStep(1.8 * absL - .9, 1000.),
          e = eStep(100. * p.y - 25.);

    // put b into sin to loop the domain to make multiple tentacles 
    // thresholding that to change the size the tentacles
    // cutout the too distorted tentacles by multiply by d
    // and cut the tentacles at the top by multiply it by e
    return eStep(sin(b) - c, -50.) * d * e;
}

#define R0(p) R(p, 0)
#define R1(p) R(p, 1)

// a warped vertical parabola at the top, and gets lower when s goes higher
float Q(vec2 p, int s)
{
    return p.y - float(10 - s) / 30. + .2 - p.x * p.x + .1 * cos(8. * p.x + float(5 * s));
}

// the details in a single tentacle with id s
float P(vec2 p, int s)
{
    float tot = Q(p, s),
          amp1 = float(50 - s) / 1000.,
          amp2 = float(1 + s),
          amp3 = .5,
          amp4 = float(5 + s);

    for(int u = 0; u <= 7; u++)
    {
        // use to "bend" the details with the arms direction
        float a = 1000. * p.x / (250. * sqr(2. * p.y - 1.) + 1.),
        // use Q as base
        // make the oral arms wAvYyYy and rough
              b = cos(amp4 * Q(p, s)),
        // pass a though atan to smooth clamp it
        // make that contibute less to make the smaller details less... parabola-y
        // make the arm wAvIeRrR and rougher as u went higher
        // add some phase to add variety
              c = amp2 * atan(a) + amp3 * b + float(2 * u * s);

        // cos(c) duplicates the arms
        // pass through atan to make the edges sharper
        tot += amp1 * atan(3. * cos(c));

        amp1 *= .6;
        amp2 *= 2.;
        amp3 *= 1.4;
        amp4 *= 2.;
    }

    return tot;
}

// a single oral arm with id s
float J(vec2 p, int s)
{
    // random number generator, gets smaller as s gets larger
    float k = float(40 - s) / 40. * cos(float(8 * s)) + .5,

    // a is the shape of the oral arms
    // it's kinda the distance to a parabola with vertex (0, 0.5)
    // and the direction is depends on k(that's why k has to be smaller as s gets higher)
          a = abs(p.x + k * sqr(p.y - .5)),
          b = p.y - float(10 - s) / 30.,
    // the shaping function of the arms
    // if it closer to the tips, it gets smaller
          c = PI / 15. + .15 * atan(-8. * b);

    // threshold a to get the shape
    // defining the edge, making it WaVyYy by multiply by the second eStep
    // cutoff the top by multiply by the last eStep
    return eStep(a - c, 500.) * eStep(P(p, s), -200.) * eStep(p.y - .7, 1000.);
}

float C(vec2 p)
{
    float tot = 0.;
    for(int s = 1; s <= 35; s++)
    {
        float a = 1.;
        float absP = abs(P(p, s));
        float E = E(p);
        for(int u = 0; u < s; u++)
        {
            a *= 1. - .75 * eStep(float(u) - .5, -100.) * J(p, u);
        }
        float b = 20. * absP - 1. + E / 5.;
        float c = 100. * absP - 3. + E;

        tot += a * J(p, s) * (eStep(Q(p, s), 3.) + .4 * eStep(b, 1.) + .4 * eStep(c, 1.));
    }

    return tot;
}

// deformed elipse
float dElip(vec2 p, float a, float b, float c, float d)
{
    return pow(abs(p.x), a - b * p.y) + 2. * sqr(p.y - c) - d;
}

float W(vec2 p, float v)
{
    return eStep(dElip(p, 7., 5., .6, .25), v);
}

float U(vec2 p)
{
    float a = dElip(p, 6.85, 5., .57, .27),
          b = dElip(p, 6.5, 5., .5, .15);

    return .45 + 2. * eStep(abs(a) - .04 + E(p) / 100., 14.) // the top glow
               + .6 * eStep(20. * abs(b) - .8 + E(p) / 5.) // secondary layer glow
               + .2 * eStep(b, 100.); // secondary layer glow... too
}

// the stripes
float K(vec2 p)
{
    // a is smallest at y = .6
    // so a * x makes the stripes bulges
    float a = 1. / (abs(.25 - .02 * sqr(10. * p.y - 6.)) + .001),
    // make a function b that outputs a big number when y = 1.4
    // and rapidly approaches 0 outside that
          b = 1. / (abs(7. - 5. * p.y) + .001);

    // So... if I take a to the b power
    // and since a is >= 4
    // at y = 1.4, a equals a really large number
    // but then drop down to 1 fast, so it creates this "pole" that gravitates the stripe into
    return eStep(cos(20. * p.x * pow(a, b)) + E(p) / 3.);
}

// the image color
vec3 H(vec2 p)
{
    // a: the tentacles
    // b: ocean background
    // d: the bell
    vec3 a, b, c, d;

    float arms = 1.;

    for(int s = 1; s <= 35; s++) arms *= 1. - .75 * J(p, s);

    a = c1 * (R0(p) + R1(p) * (1. - R0(p)) * arms);

    float gradient = 1. + 2. / 3. * p.y; // making the top brighter
          gradient -= p.x * p.x / 20.; // darkening the left and right edge
          gradient += E(p) / 20.; // very very bad dithering

    b = c2 * gradient;

    c = c3 * C(p) * (1. - R0(p)) * (1. - .6 * W(p, 500.));

    vec3 bell = vec3(W(p, 5.)); // make the bell foggy
         bell += .25 * p.y - .15; // adding highlight at the top
         bell += (vec3(.3, .25, .2) + vec3(.4, .2, 0) * (p.y - .4)) * K(p); // the stripes
         bell += vec3(.4, .05, -.3) * eStep(10. * p.y - 5. + E(p)); // add the noisy thingy at the bottom of the bell

    d = c3 * bell * W(p, 500.) * U(p);

    return a + b + c + d;
}

void mainImage(out vec4 O, vec2 I)
{
    // normalizing the coordinates
    vec2 p = vec2(2. * I - iResolution.xy) / iResolution.y;

    vec3 col = H(p);

    col = vec3(F(col.x), F(col.y), F(col.z));

    O = vec4(col, 1);
}
